import {agentSpecification,validateAgentSpecification,RULES,agentFixture,evaluateEvents,eventSummary,eventReport,compareEvents} from './agent-contract.js';
import {saveFile} from './studio.js';
import {createGardenScene} from './garden-scene.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const canonical=x=>JSON.stringify(x,(_,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.entries(v).sort(([a],[b])=>a.localeCompare(b))):v);
const readable=s=>s.replaceAll('_',' ');
const criterionNames={'current-goal':'Current goal','authorization':'Permission before editing','action-result':'Tool execution outcome','interface':'Current interface requirement','artifact-check':'Artifact verification','verified-completion':'Verified completion'};
const criterionName=c=>c?.name?.trim()||criterionNames[c?.id]||c?.definition?.trim()||'New criterion';
const field=(label,name,value,area=false,hint='')=>'<label class="design-field"><span>'+esc(label)+'</span>'+(area?'<textarea name="'+name+'" rows="3">'+esc(value)+'</textarea>':'<input name="'+name+'" value="'+esc(value)+'" maxlength="800">')+(hint?'<small>'+esc(hint)+'</small>':'')+'</label>';
const select=(label,name,entries,value)=>'<label class="design-field"><span>'+esc(label)+'</span><select name="'+name+'">'+entries.map(([id,n])=>'<option value="'+esc(id)+'" '+(id===value?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label>';
const status=s=>'<span class="event-status '+esc(s)+'">'+esc(readable(s))+'</span>';
export function renderAgentDocs(root){root.innerHTML='<section class="workspace-heading"><div><span class="eyebrow">LOCAL BEHAVIOR TOOLKIT · 0.2.0A13</span><h1>From expectations to execution evidence.</h1><p>Evaluate ordered agent events or existing multi-turn conversations.</p></div>'+(document.body.dataset.runtime==='local'?'<span class="small-note">Installed package · 0.2.0a13</span>':'<a class="button primary" href="downloads/deeproject_rhca-0.2.0a13-py3-none-any.whl" download>Download Python package ↓</a>')+'</section><section class="docs-layout"><article class="docs-copy"><h2>1. Install & create an event example</h2><pre>python -m pip install ./deeproject_rhca-0.2.0a13-py3-none-any.whl\ndeeproject init my-agent-evaluation --profile agent\ncd my-agent-evaluation</pre><p>Python 3.10+. No external runtime dependencies. The included event fixtures are author-constructed; no model is called.</p><h2>2. Evaluate and inspect</h2><pre>deeproject validate spec.json --executable\ndeeproject evaluate events.json --spec spec.json --out results/violation\ndeeproject evaluate reference-events.json --spec spec.json --out results/reference\ndeeproject view results/violation</pre><p>Results contain the original events, specification, checks, linked evidence and retained issue history. The local viewer binds to 127.0.0.1.</p><h2>3. Define your behavior protocol</h2><p>Design supports Agent behavior, RHCA and Blank profiles. Add dimensions and criteria. Specify task goals, authority, environment, success conditions, evidence, severity and anchors. Download evaluation.json.</p><p>Built-in event rules check explicit goal IDs, permission flags, tool result flags, requirement fields, verification flags and numeric limits. These checks do not establish semantic intent, authenticate recorded grants or independently verify external state. Critical violations remain visible after later passes.</p><h2>4. Supply recorded events</h2><p>An event log contains an ordered events array. Each event has a unique id, consecutive sequence, type, human-readable text and data. Observations reference a preceding action_id. See the complete fixtures below.</p><pre>{\n  "id": "my-task",\n  "model_label": "My agent",\n  "model_id": "recorded-model-version",\n  "data_type": "Recorded agent execution",\n  "events": [\n    {"id":"permission-1", "sequence":1,\n     "type":"permission", "text":"Edits authorized",\n     "data":{"scope":"workspace", "granted":true}}\n  ]\n}</pre><p>Supported event types: user, assistant, goal_update, permission, requirement_update, action, observation, verification, completion, metric. The presence of an event does not guarantee the underlying record is trustworthy. Missing evidence remains unknown or unobserved.</p><p><a class="text-link" href="data/agent-spec.json" download>Example event specification · JSON ↓</a></p><p><a class="text-link" href="data/agent-violation.json" download>Boundary violation fixture · JSON ↓</a></p><p><a class="text-link" href="data/agent-reference.json" download>Policy-following fixture · JSON ↓</a></p><h2>5. Compare controlled runs</h2><pre>deeproject compare results/reference results/violation --out comparison.json</pre><p>Use matching specification and protocol objects, including scenario and environment version and external input events. Action paths may differ. The comparison reports per-criterion failing checkpoint counts; one pair of runs does not establish reliability or causal improvement.</p><h2>BTV &amp; batch routing</h2><p><a class="text-link" href="#pipeline">Open Pipeline &amp; insights →</a></p><pre>deeproject pipeline --controlled --out results/controlled\ndeeproject pipeline --count 60 --out results/batch\ndeeproject pipeline --input input.json --out results/imported\ndeeproject btv ratings.json --out btv.json</pre><p>BTV implements the ICLR 2027 submission §3.2 Eq. (1): equal-weight complete R/H/C/A anchors, p = 1, λ = 0.5, passing threshold 2. Anchor 1 is retained separately. ratings.json is an array of objects such as {&quot;R&quot;:3,&quot;H&quot;:3,&quot;C&quot;:3,&quot;A&quot;:3}. Missing dimensions are not filled in.</p><p>The included batch has 60 programmatically constructed trajectories in Coding Agent, Healthcare Assistant and FinTech Agent. RHCA anchors are scripted; no model or calibrated semantic evaluator is called. Domains reference paper tasks P08, P04/P06 and P10; tools and event extensions are newly authored. Rules compare recorded fields, not clinical correctness or real payment state.</p><p>Batch inputs are arrays of records with id, domain, events, specification and rhca. Each rhca item contains an event_id and a scores object with all four anchors. Invalid or incomplete records go to review; event failures, BTV below threshold or Anchor 1 go to problem cases; remaining records are candidates. Originals and routing reasons remain in results.json. Browser execution supports up to 1,000 records / 100,000 events, within a 5 MB import.</p><p><a class="text-link" href="data/pipeline/input.json" download>Example input batch · JSON ↓</a> · <a class="text-link" href="data/pipeline/synthetic-pipeline-results.zip" download>Results + reproducible Python source · ZIP ↓</a></p><h2>Custom event evaluators</h2><p>Bind evaluator type python, a callable such as my_judge:check, and a version. Local evaluators receive (events_through_current, criterion). Return status, explanation, evidence, and an ordinal or numeric value when configured.</p><pre>def check(events, criterion):\n    event = events[-1]\n    return {\n        "status": "unknown",\n        "explanation": "Not enough execution evidence.",\n        "evidence": [{"event_id": event["id"],\n                      "quote": event["text"]}]\n    }</pre><p>Statuses: pass, fail, unknown, not_applicable. Pass/fail needs exact source evidence. Future or invalid quotes and evaluator exceptions become errors. Review imported Python bindings before executing code in your environment.</p><h2>Existing conversation workflows</h2><pre>deeproject init conversation-example --profile rhca\ncd conversation-example\ndeeproject run suite.json --spec spec.json \\\n  --target example_target:reply --fixture --out results/example</pre><p>Schema 1 remains supported: fixed user scripts, Python or HTTP targets, exact-text checks and prior-turn Python judges. A target receives actual message history and returns assistant text. Event-based evaluation uses schema 2 and recorded logs; it does not introduce an autonomous agent runner.</p></article><aside class="docs-aside"><h3>What is implemented</h3><p>Custom dimensions, typed result formats, six event behavior templates, numeric limits, local Python event evaluators, evidence validation, scoped recovery checkpoints, reports, comparison and 3D exploration.</p><h3>What remains to validate</h3><p>Semantic evaluator accuracy, diagnostic usefulness with real agent logs, cross-task generalization and user accessibility. No participant study or runtime enforcement is implied.</p><h3>Original evidence</h3><p>Nine recorded conversations and their separate human / LLM assessments remain available in Results. Their A ratings do not become agent action judgments.</p><a class="text-link" href="#design">Design a protocol →</a></aside></section>';}
export function createAgentStudio(api,legacy){
 let spec;try{spec=JSON.parse(localStorage.getItem('deeproject-v5-spec'))}catch{}if(!spec||spec.schema_version!==2)spec=agentSpecification();
 let step=0,selected=0,errors=[],legacyDesign=false;let committed=localStorage.getItem('deeproject-v5-committed')||canonical(spec);
 const root=()=>document.querySelector('#main'),criterion=()=>spec.criteria[selected],persist=()=>{try{localStorage.setItem('deeproject-v5-spec',JSON.stringify(spec))}catch{api.toast('Download your specification to preserve changes.')}};
 const tabs=legacy.tabs;
 function capture(){const f=document.querySelector('#agent-design-form');if(!f)return;const before=canonical(spec),data=new FormData(f);for(const k of ['domain','task','source','stakeholders','success','environment','authority'])if(data.has(k))spec.context[k]=String(data.get(k)).trim();const c=criterion();for(const k of ['name','dimension','definition','evidence','severity','result_type'])if(data.has(k))c[k]=String(data.get(k)).trim();for(const k of ['pass','fail','1','2','3'])if(data.has('anchor-'+k))c.anchors[k]=String(data.get('anchor-'+k)).trim();
  if(data.has('rule')){const old=c.evaluator,type=data.get('rule');c.evaluator={...old,type,version:'1'};for(const k of ['tool','scope','field','check_id','callable'])if(data.has('rule-'+k))c.evaluator[k]=String(data.get('rule-'+k)).trim();if(data.has('rule-limit'))c.evaluator.limit=Number(data.get('rule-limit'));}
  if(data.has('recovery-count'))spec.recovery.consecutive_checks=Number(data.get('recovery-count'));
  for(const [i,d] of spec.dimensions.entries())for(const k of ['name','definition'])if(data.has('dim-'+i+'-'+k))d[k]=String(data.get('dim-'+i+'-'+k)).trim();
  if(canonical(spec)!==before)spec.review.status='draft';persist();
 }
 function commit(){capture();errors=validateAgentSpecification(spec);if(errors.length){design();return false;}if(canonical(spec)!==committed){spec.version++;committed=canonical(spec);localStorage.setItem('deeproject-v5-committed',committed);}persist();return true;}
 function preset(profile){spec=agentSpecification(profile);selected=0;step=0;errors=[];legacyDesign=false;committed=canonical(spec);localStorage.setItem('deeproject-v5-committed',committed);persist();design();}
 function specCard(){return '<div class="spec-summary spec-review"><span class="eyebrow">'+esc(spec.id)+' / V'+spec.version+' · '+esc(spec.profile)+'</span><h2>'+esc(spec.context.task)+'</h2><p>'+esc(spec.context.authority)+'</p>'+spec.dimensions.map(d=>{const list=spec.criteria.filter(c=>c.dimension===d.id);if(!list.length)return '';return '<details class="review-category"><summary><span>'+esc(d.name)+'</span><small>'+list.length+' '+(list.length===1?'criterion':'criteria')+'</small></summary><div>'+list.map(c=>'<article class="review-criterion"><h3>'+esc(criterionName(c))+'</h3><p>'+esc(c.definition)+'</p><details class="criterion-evidence-details"><summary>Evidence & evaluation details</summary><p>'+esc(c.evidence)+'</p><p class="small-note">'+esc(c.severity==='critical'?'Critical boundary':'Standard')+' · '+esc(c.result_type==='binary'?'Pass / fail':c.result_type)+' · '+esc(RULES[c.evaluator.type]||'Custom Python evaluator')+'</p><dl class="anchor-list">'+(c.result_type==='ordinal'?['1','2','3']:['pass','fail']).map(k=>'<div><dt>'+k+'</dt><dd>'+esc(c.anchors[k])+'</dd></div>').join('')+'</dl></details></article>').join('')+'</div></details>';}).join('')+'<p class="small-note">Source: '+esc(spec.context.source)+'. No assessment has been performed by saving this specification.</p></div>';}
 function criteriaGroups(){return '<div class="criteria-groups" aria-label="Criteria grouped by behavior category">'+spec.dimensions.map(d=>{const list=spec.criteria.map((c,i)=>({c,i})).filter(x=>x.c.dimension===d.id);return '<details class="criteria-category" '+(criterion().dimension===d.id?'open':'')+'><summary><span>'+esc(d.name)+'</span><small>'+list.length+'</small></summary><div class="criteria-category-items">'+list.map(({c,i})=>'<button type="button" data-agent-criterion="'+i+'" class="'+(i===selected?'active':'')+'" '+(i===selected?'aria-current="true"':'')+'>'+esc(criterionName(c))+'</button>').join('')+'<button type="button" class="text-link" data-agent="add-criterion" data-agent-dimension="'+esc(d.id)+'" aria-label="Add criterion to '+esc(d.name)+'">+ Add criterion</button></div></details>';}).join('')+'</div>';}

 function design(){if(legacyDesign){legacy.design();return;}let body='';const c=criterion();
  if(step===0)body=select('Start from a profile','profile',[['agent','Agent behavior'],['rhca','RHCA'],['blank','Blank profile']],spec.profile)+field('Domain','domain',spec.context.domain)+field('Task & goal','task',spec.context.task,true)+field('Success condition','success',spec.context.success,true)+field('Environment & available actions','environment',spec.context.environment)+field('Authority & human control','authority',spec.context.authority,true)+'<details class="dimension-editor"><summary>Source & stakeholders</summary>'+field('Requirement source','source',spec.context.source,true)+field('People whose expectations matter','stakeholders',spec.context.stakeholders)+'</details>';
  if(step===1)body=criteriaGroups()+'<section class="selected-criterion-editor"><span class="eyebrow">EDIT CRITERION</span>'+field('Criterion name','name',criterionName(c))+field('Observable behavioral criterion','definition',c.definition,true)+select('Category','dimension',spec.dimensions.map(d=>[d.id,d.name]),c.dimension)+'<details class="criterion-options"><summary>Assessment settings</summary>'+select('Severity','severity',[['standard','Standard'],['critical','Critical boundary']],c.severity)+select('Result type','result_type',[['binary','Pass / fail'],['ordinal','Anchored 1–3 · local Python evaluator'],['numeric','Numeric threshold or local evaluator']],c.result_type)+'</details>'+(spec.criteria.length>1?'<button type="button" class="text-link criterion-remove" data-agent="remove-criterion">Remove this criterion</button>':'')+'</section><details class="dimension-editor"><summary>Edit dimensions · '+spec.dimensions.length+' configured</summary><p class="small-note">Dimensions organize your criteria. RHCA is an optional profile, not a fixed limit.</p>'+spec.dimensions.map((d,i)=>'<div class="dimension-edit-row">'+field('Name','dim-'+i+'-name',d.name)+field('Definition','dim-'+i+'-definition',d.definition,true)+'<button type="button" class="text-link" data-agent-remove-dimension="'+i+'">Remove dimension</button></div>').join('')+'<button type="button" class="quiet-button" data-agent="add-dimension">+ Add dimension</button></details>';
  if(step===2){const e=c.evaluator;body='<div class="selected-criterion-context"><div><span class="eyebrow">'+esc(spec.dimensions.find(d=>d.id===c.dimension)?.name)+'</span><h3>'+esc(criterionName(c))+'</h3></div><button type="button" class="text-link" data-agent-step="1">Change criterion ↗</button></div>'+field('Required evidence','evidence',c.evidence,true,'Event checks reference the trigger and prior recorded evidence. Missing evidence is not a pass.')+(c.result_type==='ordinal'?['1','2','3']:['pass','fail']).map(k=>field('Anchor · '+k,'anchor-'+k,c.anchors[k],true)).join('')+select('Executable rule','rule',[...Object.entries(RULES),['python','Custom Python event evaluator · local']],e.type);
   const params={authorization:['tool','scope'],goal_alignment:['tool'],state_alignment:['tool','field'],action_outcome:['tool'],verification:['tool','check_id'],completion_verification:['tool','check_id'],numeric_limit:['field'],python:['callable']}[e.type]||[];
   body+=params.map(k=>field(readable(k),'rule-'+k,e[k]||'',false)).join('')+(e.type==='numeric_limit'?field('Maximum allowed value','rule-limit',e.limit??0):'')+'<p class="small-note">Built-in rules inspect recorded fields, not semantic intent. Ordinal ratings require a local Python evaluator. Unbound criteria remain drafts.</p><label class="design-field"><span>Consecutive applicable passes required for recovery</span><input type="number" name="recovery-count" min="2" max="100" value="'+spec.recovery.consecutive_checks+'"><small>Unknown/error breaks the streak. Historical violations are always retained.</small></label>';
  }
  if(step===3)body=specCard()+'<p class="small-note">Review the source, scope and evidence assumptions before using this protocol. Saving is not an organizational approval.</p>';
  root().innerHTML=tabs('design')+'<section class="workspace-heading"><div><span class="eyebrow">BEHAVIORAL EVALUATION DESIGN</span><h1>Define how an agent should act.</h1><p>Goals, authority, actions and evidence — across the task.</p></div><button class="quiet-button" data-agent="import-spec">Import specification ↗</button></section><div class="design-layout"><aside class="design-steps">'+['Task & boundaries','Behavior & dimensions','Rules & evidence','Review & package'].map((title,i)=>'<button data-agent-step="'+i+'" class="'+(i===step?'active':'')+'" '+(i===step?'aria-current="step"':'')+'><span>0'+(i+1)+'</span>'+title+'</button>').join('')+'</aside><section class="design-sheet"><div class="sheet-heading"><span class="eyebrow">STEP '+(step+1)+' OF 4</span><span class="small-note">Local draft · v'+spec.version+'</span></div><h2>'+['Set the task and its boundaries.','Make the behavior observable.','Specify the check and its evidence.','Review the executable protocol.'][step]+'</h2>'+(errors.length?'<div role="alert" class="validation-errors">'+errors.map(e=>'<p>'+esc(e)+'</p>').join('')+'</div>':'')+'<form id="agent-design-form">'+body+'<div class="design-actions">'+(step?'<button type="button" class="quiet-button" data-agent="back">← Back</button>':'<span class="small-note">Changes save in this browser.</span>')+'<div>'+(step===3?'<button type="button" class="button secondary" data-agent="export-spec">Download specification ↓</button>':'')+'<button class="button primary" type="submit">'+(step===3?'Save & continue to Run →':'Continue →')+'</button></div></div></form></section></div><input type="file" id="agent-spec-file" accept=".json,application/json" hidden>';
 }
 function runPage(){if(legacyDesign){legacy.run();return;}root().innerHTML=tabs('run')+'<section class="workspace-heading"><div><span class="eyebrow">CHECK AGENT BEHAVIOR</span><h1>Evaluate the actions, not only the reply.</h1><p>Apply your specification to ordered execution events.</p></div><a class="text-link" href="#docs">Local package & event format ↗</a></section><div class="run-layout"><section class="run-sheet"><span class="eyebrow">AUTHOR-CONSTRUCTED REPLAY · NO MODEL RUN</span><h2>Explore the behavior protocol.</h2>'+select('Event fixture','agent-variant',[['violation','Continues after revocation, then corrects'],['reference','Pauses and respects updated requirements']],'violation')+'<p>Both fixtures encounter an initial execution failure and end with successful artifact checks. Their behavior histories differ.</p><p class="small-note">The fixture uses the original Agent behavior preset. It validates execution paths, not model performance or general agent reliability.</p><button class="button primary" data-agent="replay">Evaluate fixture →</button><button class="text-link" data-agent="use-agent-preset">Load original Agent behavior preset</button><div class="inline-error" id="agent-run-message" role="status"></div></section><aside class="local-harness"><span class="eyebrow">YOUR RECORDED EVENTS</span><h2>Evaluate your own task.</h2><p>'+esc(spec.id)+' · v'+spec.version+' · '+spec.criteria.length+' criteria</p><label class="design-field"><span>Paste an event log · JSON</span><textarea id="event-log-input" rows="7" spellcheck="false" placeholder="An object containing ordered events"></textarea></label><button class="button secondary" data-agent="evaluate-log">Evaluate pasted events →</button><p class="small-note">Only the configured rules run. Imported events are assumed accurate; the evaluator does not authenticate permission or verify external state independently.</p><pre>deeproject evaluate events.json \\\n  --spec evaluation.json \\\n  --out results/agent</pre></aside></div>';}
 function row(run){const event=run.record_type==='agent_events',n=event?run.events.length:run.turns.length;return '<article class="result-row"><div><h3>'+esc(run.model_label)+'</h3><p>'+esc(run.data_type||'Recorded conversation')+'</p><p>'+n+' '+(event?'events · '+eventSummary(run).critical_violations+' critical violation(s) retained': 'turns')+'</p></div><a class="button secondary" href="'+api.route('diagnostics',run.id,1,event?run.specification.dimensions[0].id:run.dimension)+'">Inspect →</a><a class="text-link" href="'+api.route('garden',run.id,1,event?run.specification.dimensions[0].id:run.dimension)+'">Garden ↗</a></article>';}
 async function results(){const mine=[];for(const r of api.index.runs.filter(x=>x.record_type==='agent_events'||/^(RUN|AGENT|IMPORT|FIXTURE)-/.test(x.id)))try{mine.push(await api.getRun(r.id))}catch{}if(location.hash.split('?')[0]!=='#workbench')return;root().innerHTML=tabs('workbench')+'<section class="workspace-heading"><div><span class="eyebrow">BEHAVIOR & EXECUTION EVIDENCE</span><h1>See what happened along the way.</h1><p>Task outcomes, current checks and historical violations remain separate.</p></div><div class="heading-actions"><button class="quiet-button" data-action="import">Import results ↗</button><a class="button secondary" href="#compare">Compare runs ⇄</a></div></section><section class="result-section"><div class="section-label"><h2>Evaluations & event examples</h2><a class="text-link" href="#run">Evaluate events +</a></div>'+(mine.length?mine.reverse().map(row).join(''):'<div class="results-empty"><p>Replay the agent fixtures or evaluate your event log.</p><a href="#run" class="button primary">Start an evaluation →</a></div>')+'</section><details class="recorded-library"><summary>Recorded conversation examples · 3 domains / 3 models</summary><p class="small-note">Original A ratings and human / LLM records are preserved. These logs do not contain agent action or environment evidence.</p>'+api.index.runs.filter(x=>/^R0[1-9]$/.test(x.id)).map(r=>'<article class="result-row"><div><h3>'+esc(r.model_label)+'</h3><p>'+esc(api.index.scenarios.find(s=>s.id===r.scenario)?.name)+' · '+r.turn_count+' turns</p></div><a class="button secondary" href="'+api.route('diagnostics',r.id,1,'A')+'">Inspect →</a></article>').join('')+'</details>';}
 async function comparePage(){const runs=[];for(const r of api.index.runs)try{const x=await api.getRun(r.id);if(x.record_type==='agent_events')runs.push(x)}catch{}if(!runs.length){legacy.compare();return;}const opts=runs.map(r=>[r.id,r.model_label+' · '+r.id]);root().innerHTML=tabs('workbench')+'<section class="workspace-heading"><div><span class="eyebrow">CONTROLLED COMPARISON</span><h1>Compare behavior histories.</h1><p>Match the specification, external task protocol and environment. Agent action paths may differ.</p></div></section><section class="compare-sheet">'+(runs.length<2?'<p>Evaluate both event fixtures to compare their histories.</p><a href="#run" class="text-link">Evaluate another fixture →</a>':'<div class="field-pair">'+select('Baseline','event-baseline',opts,runs[0].id)+select('Candidate','event-candidate',opts,runs.at(-1).id)+'</div><button class="button primary" data-agent="compare">Compare runs →</button><div id="event-comparison" aria-live="polite"></div>')+'</section>';}
 document.addEventListener('submit',e=>{if(e.target.id!=='agent-design-form')return;e.preventDefault();capture();errors=[];if(step<3){step++;design();window.scrollTo(0,0)}else if(commit())location.hash='#run';});
 document.addEventListener('input',e=>{if(e.target.closest('#agent-design-form'))capture()});
 document.addEventListener('change',async e=>{if(e.target.name==='profile'&&e.target.closest('#agent-design-form')){preset(e.target.value);return;}if(e.target.closest('#agent-design-form')){capture();if(['rule','result_type','dimension'].includes(e.target.name))design();}if(e.target.id==='agent-spec-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('Choose a specification smaller than 1 MB.');importSpec(JSON.parse(await file.text()));}catch(err){api.toast(err.message)}}});
 document.addEventListener('click',async e=>{const button=e.target.closest('[data-agent]'),action=button?.dataset.agent,go=e.target.closest('[data-agent-step]')?.dataset.agentStep,ci=e.target.closest('[data-agent-criterion]')?.dataset.agentCriterion,remove=e.target.closest('[data-agent-remove-dimension]')?.dataset.agentRemoveDimension;
  if(go!==undefined){capture();step=Number(go);errors=[];design();}if(ci!==undefined){capture();selected=Number(ci);step=1;design();}
  if(remove!==undefined){capture();const d=spec.dimensions[Number(remove)];if(spec.criteria.some(c=>c.dimension===d.id)||spec.dimensions.length===1){api.toast('Move its criteria to another dimension before removing it.');return;}spec.dimensions.splice(Number(remove),1);persist();design();}
  if(!action)return;
  if(action==='back'){capture();step--;design();}if(action==='add-dimension'){capture();spec.dimensions.push({id:'custom-'+Date.now(),name:'Custom behavior',definition:'Define the scope of this behavior.'});persist();design();document.querySelector('.dimension-editor').open=true;}
  if(action==='add-criterion'){capture();spec.criteria.push({id:'criterion-'+Date.now(),name:'New criterion',dimension:button.dataset.agentDimension||criterion().dimension,definition:'',evidence:'',severity:'standard',result_type:'binary',anchors:{pass:'',fail:''},evaluator:{type:'unbound',version:'1'}});selected=spec.criteria.length-1;step=1;persist();design();}
  if(action==='remove-criterion'&&spec.criteria.length>1){capture();spec.criteria.splice(selected,1);selected=Math.max(0,selected-1);persist();design();}
  if(action==='import-spec')document.querySelector('#agent-spec-file').click();if(action==='export-spec'&&commit()){saveFile('evaluation.json',JSON.stringify(spec,null,2),'application/json');design();}
  if(action==='use-agent-preset'){preset('agent');location.hash='#run';runPage();}
  if(action==='replay'||action==='evaluate-log')try{const run=action==='replay'?agentFixture(document.querySelector('[name="agent-variant"]').value,spec):evaluateEvents(JSON.parse(document.querySelector('#event-log-input').value),spec);if(action==='evaluate-log'){run.source_run_id=run.id;run.id='AGENT-'+Date.now();run.scenario=run.scenario||'local-agent';run.kind=run.kind||'recorded';run.model_label=run.model_label||'Imported event log';run.model_id=run.model_id||'not-recorded';run.dimension=spec.dimensions[0].id;run.data_type=run.data_type||'Imported agent event log · provenance supplied by importer';run.execution_mode=run.execution_mode||'recorded-event-evaluation';}api.addRun(run);location.hash=api.route('diagnostics',run.id,1,spec.dimensions[0].id);}catch(err){api.toast(err.message);const m=document.querySelector('#agent-run-message');if(m)m.textContent=err.message;}
  if(action==='compare'){const a=await api.getRun(document.querySelector('[name="event-baseline"]').value),b=await api.getRun(document.querySelector('[name="event-candidate"]').value),r=compareEvents(a,b);if(a.id===b.id){r.comparable=false;r.reasons.push('Choose two different runs.');}document.querySelector('#event-comparison').innerHTML=r.comparable?'<div class="comparison-rows">'+r.changes.map(c=>'<div><span>'+esc(criterionName(b.specification.criteria.find(x=>x.id===c.criterion_id)))+'</span><span>'+c.baseline_failures+' → '+c.candidate_failures+' failing checkpoints</span></div>').join('')+'</div><p class="small-note">'+esc(r.note)+'</p><button class="text-link" id="export-event-comparison">Download comparison · JSON ↓</button>':'<div class="validation-errors">'+r.reasons.map(x=>'<p>'+esc(x)+'</p>').join('')+'</div>';const out=document.querySelector('#export-event-comparison');if(out)out.onclick=()=>saveFile('agent-comparison.json',JSON.stringify(r,null,2),'application/json');}
 });
 function importSpec(value){if(value.schema_version!==2){legacyDesign=true;legacy.importSpec(value);return;}const errors=validateAgentSpecification(value);if(errors.length)throw Error(errors.join(' '));spec=structuredClone(value);spec.review=spec.review||{status:'draft',note:''};legacyDesign=false;selected=0;step=3;committed=canonical(spec);localStorage.setItem('deeproject-v5-committed',committed);persist();if(location.hash==='#design')design();else location.hash='#design';}
 return {tabs,design,run:runPage,results,compare:comparePage,importSpec};
}

export function createEventViewer(api){let scene=null,run,position,dimension,criterionId=null,showAll=false,inspecting=false;
 const root=()=>document.querySelector('#main'),criteria=()=>run.specification.criteria.filter(c=>c.dimension===dimension),selectedCriterion=()=>run.specification.criteria.find(c=>c.id===criterionId)||criteria()[0];
 const move=(seq,dim=dimension)=>{location.hash=api.route(api.page(),run.id,seq,dim)+(criterionId?'&criterion='+encodeURIComponent(criterionId):'');};
 function assessment(c,at=position){return run.events.slice(0,at).flatMap(e=>e.evaluations||[]).filter(a=>a.criterion_id===c.id&&a.status!=='not_applicable').at(-1);}
 function historyFailed(c,at=position){return run.events.slice(0,at).some(e=>e.evaluations?.some(a=>a.criterion_id===c.id&&a.status==='fail'));}
 function evidence(a){return (a?.evidence||[]).map(v=>'<a class="event-evidence" href="'+api.route(api.page(),run.id,run.events.find(e=>e.id===v.event_id)?.sequence||1,dimension)+'"><strong>'+esc(v.event_id)+'</strong><span>'+esc(v.quote)+'</span></a>').join('');}
 function panel(){if(api.page()==='garden'&&!inspecting)return '<div class="event-panel" hidden></div>';const c=selectedCriterion(),a=c&&assessment(c),issue=c&&run.issues.find(i=>i.criterion_id===c.id);return '<div class="event-panel">'+(api.page()==='garden'?'<div class="panel-top"><button class="icon-button" data-event="close-panel" aria-label="Close evidence panel">×</button></div>':'<label class="design-field"><span>Behavior module</span><select id="event-dimension">'+run.specification.dimensions.map(d=>'<option value="'+esc(d.id)+'" '+(d.id===dimension?'selected':'')+'>'+esc(d.name)+'</option>').join('')+'</select></label>')+'<label class="design-field"><span>Criterion</span><select id="event-criterion">'+criteria().map(x=>'<option value="'+esc(x.id)+'" '+(x.id===c?.id?'selected':'')+'>'+esc(criterionName(x))+'</option>').join('')+'</select></label>'+(c?'<h3>'+esc(c.definition)+'</h3><span class="eyebrow">LATEST CHECK THROUGH EVENT '+position+'</span>'+status(a?.status||'unobserved')+'<p>'+esc(a?.explanation||'No applicable check has been observed by this event.')+'</p><p class="small-note">'+esc(c.severity)+' · '+esc(a?.source||c.evaluator.type)+'</p>'+evidence(a)+(historyFailed(c)?'<p class="history-note">Historical violation retained. Current passing evidence does not erase prior actions.</p>':'')+(issue?'<details><summary>Observed issue history</summary><p>As of event '+position+': '+esc(run.events.slice(0,position).filter(e=>e.evaluations.some(a=>a.criterion_id===c.id&&a.status==='fail')).map(e=>e.id).join(', ')||'No failure yet observed')+'</p><p class="small-note">'+esc(issue.recovery)+'</p><p class="small-note">Scope: '+esc(issue.scope)+'</p></details>':''):'<p>No criteria are configured in this dimension.</p>')+(api.page()==='garden'&&c?'<a class="button secondary full" href="'+api.route('diagnostics',run.id,position,dimension)+'&amp;criterion='+encodeURIComponent(c.id)+'">View evidence →</a>':'')+'</div>';}
 function details(){const e=run.events[position-1],applied=e.evaluations.filter(a=>a.status!=='not_applicable');return '<article class="event-detail"><span class="eyebrow">EVENT '+position+' / '+run.events.length+' · '+esc(e.type)+'</span><h2>'+esc(e.text)+'</h2><p class="small-note">'+esc(e.id)+'</p><dl class="event-data">'+Object.entries(e.data).map(([k,v])=>'<div><dt>'+esc(readable(k))+'</dt><dd>'+esc(typeof v==='object'?JSON.stringify(v):v)+'</dd></div>').join('')+'</dl><div class="event-checks">'+applied.map(a=>'<button data-event-criterion="'+esc(a.criterion_id)+'"><span>'+esc(criterionName(run.specification.criteria.find(c=>c.id===a.criterion_id)))+'</span>'+status(a.status)+'</button>').join('')+'</div>'+(!applied.length?'<p class="small-note">This event provides context. No configured rule applies directly.</p>':'')+'</article>';}
 function summary(){const s=eventSummary(run);return '<div class="event-overview"><div><span class="eyebrow">FULL RECORD · '+run.events.length+' EVENTS</span><h2>'+s.critical_violations+' critical violation'+(s.critical_violations===1?'':'s')+' retained</h2><p>'+s.failures+' failing checkpoints · '+s.unknown+' unknown checkpoints · '+s.errors+' evaluator errors</p></div><p class="small-note">'+esc(s.note)+(s.unobserved_criteria.length?' Unobserved criteria: '+esc(s.unobserved_criteria.join(', '))+'.':'')+'</p></div>';}
 function findings(){const issues=run.issues.slice().sort((a,b)=>(a.severity==='critical'?-1:0)-(b.severity==='critical'?-1:0)||a.first_observed-b.first_observed);return '<section class="event-findings" aria-label="Full-record findings">'+issues.slice(0,showAll?undefined:3).map(i=>'<a href="'+api.route('diagnostics',run.id,i.first_observed,i.dimension)+'"><span class="eyebrow">'+esc(i.severity)+' · FIRST OBSERVED '+esc(i.first_event_id)+'</span><strong>'+esc(i.title)+'</strong><span>'+i.failing_events.length+' failed check(s) · latest '+esc(readable(i.status))+'</span></a>').join('')+(issues.length>3?'<button class="text-link" data-event="all-findings">'+(showAll?'Show fewer':'Show all '+issues.length+' findings')+'</button>':'')+'</section>';}
 function heading(){return '<section class="workspace-heading"><div><a class="back-link" href="#workbench">← Results</a><h1>Agent behavior, in context.</h1><p>'+esc(run.model_label)+' · '+esc(run.data_type)+'</p></div><div class="heading-actions"><button class="quiet-button" data-event="details">Run details ⓘ</button><button class="quiet-button" data-event="report">Export report ↓</button>'+(api.page()==='garden'?'':'<a class="button secondary" href="'+api.route('garden',run.id,position,dimension)+'">Explore garden ↗</a>')+'</div></section>';}
 function render(r,pos,dim){dispose();if(run?.id!==r.id||dimension!==dim)inspecting=false;run=r;position=Math.max(1,Math.min(pos,r.events.length));dimension=r.specification.dimensions.some(d=>d.id===dim)?dim:r.specification.dimensions[0].id;const requestedCriterion=new URLSearchParams(location.hash.split('?')[1]||'').get('criterion');if(requestedCriterion&&criteria().some(c=>c.id===requestedCriterion))criterionId=requestedCriterion;if(!criteria().some(c=>c.id===criterionId))criterionId=criteria()[0]?.id;const garden=api.page()==='garden';
  root().innerHTML=(garden?'':api.tabs('workbench'))+heading()+(garden?'<div class="agent-garden-header"><label class="design-field"><span>Visible behavior module</span><select id="event-dimension">'+run.specification.dimensions.map(d=>'<option value="'+esc(d.id)+'" '+(d.id===dimension?'selected':'')+'>'+esc(d.name)+'</option>').join('')+'</select></label><p class="small-note">One planting per criterion in this module. Color shows its latest applicable check; history labels retain earlier violations.</p></div>':summary()+findings())+(garden?'<div class="agent-garden-layout'+(inspecting?' inspecting':'')+'"><div class="garden-stage"><canvas id="event-garden-canvas" aria-hidden="true"></canvas><div class="dimension-markers" id="event-markers">'+criteria().map(c=>{const a=assessment(c),s=a?.status||'unobserved';return '<button class="dim-marker '+(s==='pass'?'meets':s==='fail'?'fails':'unassessed')+'" data-event-criterion="'+esc(c.id)+'"><span><strong>'+esc(criterionName(c))+'</strong><small>'+esc(readable(s))+(historyFailed(c)?' · prior violation':'')+'</small></span></button>';}).join('')+'</div><div class="scene-tools"><button class="quiet-button" data-event="overview">Overview ↗</button><span></span><button class="icon-button" data-event="left" aria-label="Rotate garden left">↶</button><button class="icon-button" data-event="right" aria-label="Rotate garden right">↷</button><button class="icon-button" data-event="zoom-in" aria-label="Zoom in">+</button><button class="icon-button" data-event="zoom-out" aria-label="Zoom out">−</button></div></div>'+panel()+'</div><div class="event-playback"><button class="quiet-button" data-event="previous" '+(position===1?'disabled':'')+'>← Previous event</button><label class="scrubber"><span class="sr-only">Execution event</span><input type="range" id="event-timeline" aria-label="Execution event" min="1" max="'+run.events.length+'" value="'+position+'"></label><span>'+position+' / '+run.events.length+'</span><button class="quiet-button" data-event="next" '+(position===run.events.length?'disabled':'')+'>Next event →</button></div>'+details():'<section class="event-workspace"><nav class="event-rail" aria-label="Recorded execution events">'+run.events.map(e=>'<a href="'+api.route('diagnostics',run.id,e.sequence,dimension)+'" '+(e.sequence===position?'aria-current="step"':'')+'><span>'+String(e.sequence).padStart(2,'0')+'</span><div><strong>'+esc(readable(e.type))+'</strong><small>'+esc(e.id)+'</small></div>'+(e.evaluations.some(a=>a.status==='fail')?'<i class="event-fail-dot" aria-label="Failing check"></i>':'')+'</a>').join('')+'</nav>'+details()+panel()+'</section>')+'<p class="small-note event-scope-note">Checks assume the recorded fields and event order are accurate. They do not authenticate permission, reconstruct hidden reasoning or independently inspect an external environment.</p>';
  if(garden){const list=criteria();scene=createGardenScene(document.querySelector('#event-garden-canvas'),document.querySelector('#event-markers'),()=>({statuses:list.map(c=>{const s=assessment(c)?.status;return s==='pass'?'meets':s==='fail'?'fails':'unassessed'}),turn:position}),i=>{criterionId=list[i].id;inspecting=true;refreshPanel();});let played=false;try{played=sessionStorage.getItem('deeproject-garden-entered')==='yes';sessionStorage.setItem('deeproject-garden-entered','yes')}catch{}if(!played&&!matchMedia('(prefers-reduced-motion: reduce)').matches){scene.enter();const gate=document.createElement('div');gate.className='garden-entry';gate.innerHTML='<span>Entering the garden</span><button class="quiet-button" data-event="skip-entry">Skip animation →</button>';document.querySelector('.garden-stage').append(gate);setTimeout(()=>gate.remove(),2400);}}
 }
 function refreshPanel(){const p=document.querySelector('.event-panel');if(p)p.outerHTML=panel();document.querySelector('.agent-garden-layout')?.classList.toggle('inspecting',inspecting);}
 function dispose(){scene?.dispose();scene=null;}
 document.addEventListener('change',e=>{if(!run||!document.querySelector('.event-detail'))return;if(e.target.id==='event-dimension'){criterionId=null;inspecting=false;move(position,e.target.value)}if(e.target.id==='event-criterion'){criterionId=e.target.value;refreshPanel();}});
 document.addEventListener('input',e=>{if(e.target.id==='event-timeline')move(Number(e.target.value))});
 document.addEventListener('click',e=>{if(!run||!document.querySelector('.event-detail'))return;const c=e.target.closest('[data-event-criterion]')?.dataset.eventCriterion,a=e.target.closest('[data-event]')?.dataset.event;if(c){criterionId=c;inspecting=true;const cr=run.specification.criteria.find(x=>x.id===c);if(cr.dimension!==dimension){dimension=cr.dimension;move(position)}else{refreshPanel();scene?.focus(criteria().findIndex(x=>x.id===c));}}if(a==='previous')move(position-1);if(a==='next')move(position+1);if(a==='overview'){inspecting=false;refreshPanel();scene?.overview();}if(a==='close-panel'){inspecting=false;refreshPanel();scene?.overview();document.querySelector('[data-event-criterion="'+CSS.escape(criterionId)+'"]')?.focus();}if(a==='left')scene?.rotate(-.3);if(a==='right')scene?.rotate(.3);if(a==='zoom-in')scene?.zoom(-2);if(a==='zoom-out')scene?.zoom(2);if(a==='skip-entry'){scene?.skipEntry();document.querySelector('.garden-entry')?.remove();}if(a==='all-findings'){showAll=!showAll;render(run,position,dimension);}if(a==='report')api.dialog('Export agent results','<p>Findings include historical violations and event evidence. Specifications are downloaded from Design.</p><button class="button primary" id="event-export-report">Report · Text ↓</button> <button class="button secondary" id="event-export-json">Results · JSON ↓</button>');if(a==='report'){document.querySelector('#event-export-report').onclick=()=>saveFile('agent-findings.txt',eventReport(run));document.querySelector('#event-export-json').onclick=()=>saveFile('agent-results.json',JSON.stringify(run,null,2),'application/json');}if(a==='details')api.dialog('Run details','<dl class="metadata-list">'+[['Case',run.id],['Data type',run.data_type],...(!run.fixture?[['Model family',run.family||'Not recorded'],['Version',run.model_id||'Not recorded']]:[])].map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>');});
 return {render,dispose};
}
